"use strict";
import { useQuery } from "@tanstack/react-query";
import { usePublicClient } from "wagmi";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { getAbstractContracts } from "uniswap/src/constants/abstractContracts";
import { MANAGED_REWARD_ABI, MANAGED_VAULT_REWARD_CONFIGS } from "pages/Locks/constants/managedVaultRewards";
const WEEK_IN_SECONDS = 7 * 24 * 60 * 60;
const getEpochTimestamps = () => {
  const currentSeconds = Math.floor(Date.now() / 1e3);
  const currentEpochStart = Math.floor(currentSeconds / WEEK_IN_SECONDS) * WEEK_IN_SECONDS;
  return {
    current: currentEpochStart,
    previous: currentEpochStart - WEEK_IN_SECONDS
  };
};
export function useManagedVaultAprs(chainId = UniverseChainId.Mainnet) {
  const publicClient = usePublicClient({ chainId });
  const { current: currentEpoch, previous: previousEpoch } = getEpochTimestamps();
  const managedVaultConfigs = Object.values(MANAGED_VAULT_REWARD_CONFIGS);
  const managedVaultIdsKey = managedVaultConfigs.map((config) => config.managedTokenId).join(",");
  const queryEnabled = Boolean(publicClient && managedVaultConfigs.length > 0);
  return useQuery({
    // Use currentEpoch in key so cache updates when epoch flips
    queryKey: ["managed-vault-aprs", chainId, currentEpoch, managedVaultIdsKey],
    enabled: queryEnabled,
    staleTime: 6e4,
    refetchInterval: 12e4,
    queryFn: async () => {
      if (!publicClient || managedVaultConfigs.length === 0) {
        return {};
      }
      const abstractContracts = getAbstractContracts(chainId);
      const abxAddress = abstractContracts?.abx;
      if (!abxAddress) {
        return {};
      }
      const contracts = managedVaultConfigs.flatMap((config) => [
        {
          address: config.rewardContract,
          abi: MANAGED_REWARD_ABI,
          functionName: "tokenRewardsPerEpoch",
          args: [abxAddress, BigInt(currentEpoch)]
        },
        {
          address: config.rewardContract,
          abi: MANAGED_REWARD_ABI,
          functionName: "tokenRewardsPerEpoch",
          args: [abxAddress, BigInt(previousEpoch)]
        }
      ]);
      const results = await publicClient.multicall({
        allowFailure: true,
        contracts
      });
      const aprMap = {};
      managedVaultConfigs.forEach((config, index) => {
        const currentResult = results[index * 2];
        const previousResult = results[index * 2 + 1];
        const currentRewards = currentResult?.status === "success" ? currentResult.result : 0n;
        const previousRewards = previousResult?.status === "success" ? previousResult.result : 0n;
        const rewardsPerEpoch = currentRewards > previousRewards ? currentRewards : previousRewards;
        const epochUsed = currentRewards > previousRewards ? currentEpoch : previousEpoch;
        aprMap[config.managedTokenId] = {
          rewardsPerEpoch,
          epochStartTimestamp: epochUsed
        };
      });
      return aprMap;
    }
  });
}
