"use strict";
export function safeBigInt(value) {
  if (typeof value === "bigint") {
    return value;
  }
  if (typeof value === "number") {
    return BigInt(Math.trunc(value));
  }
  if (typeof value === "string") {
    try {
      return BigInt(value);
    } catch (error) {
      console.warn("safeBigInt: failed to parse string value", value, error);
      return 0n;
    }
  }
  return 0n;
}
