"use strict";
import { popupRegistry } from "components/Popups/registry";
import { PopupType } from "components/Popups/types";
import { useVeABXUserLocks } from "hooks/useVeABXLocks";
import { useCallback, useState, useEffect } from "react";
import { useAccount } from "wagmi";
import { useLockContract } from "./useLockContract";
export function useUnlockFlow() {
  const { address: account } = useAccount();
  const { refetch: refetchUserLocks } = useVeABXUserLocks(account);
  const {
    withdraw,
    isWritePending,
    isConfirming,
    isSuccess,
    writeError,
    transactionHash
  } = useLockContract();
  const [flowState, setFlowState] = useState({
    step: "idle"
  });
  const executeUnlock = useCallback(async (tokenId) => {
    if (!account) return;
    setFlowState({
      step: "confirming",
      tokenId
    });
    try {
      await withdraw(tokenId);
    } catch (error) {
      console.error("Unlock failed:", error);
      const errorMessage = error instanceof Error ? error.message : "Failed to unlock ABX tokens";
      const isUserRejection = errorMessage.toLowerCase().includes("user rejected") || errorMessage.toLowerCase().includes("user denied") || errorMessage.toLowerCase().includes("rejected by user");
      if (isUserRejection) {
        setFlowState({ step: "idle" });
        popupRegistry.addPopup({
          type: PopupType.LockError,
          content: {
            type: "error",
            title: "Transaction Cancelled",
            description: "Unlock transaction was cancelled by user",
            action: "withdraw"
          }
        }, `lock-unlock-cancelled-${Date.now()}`, 5e3);
      } else {
        setFlowState({
          step: "error",
          error: errorMessage,
          tokenId
        });
        popupRegistry.addPopup({
          type: PopupType.LockError,
          content: {
            type: "error",
            title: "Unlock Failed",
            description: `Failed to unlock ABX tokens: ${errorMessage}`,
            action: "withdraw"
          }
        }, `lock-unlock-error-${Date.now()}`, 1e4);
      }
    }
  }, [account, withdraw]);
  const handleSuccess = useCallback(async (tokenId) => {
    setFlowState({
      step: "success",
      transactionHash,
      tokenId
    });
    popupRegistry.addPopup({
      type: PopupType.LockSuccess,
      content: {
        type: "success",
        title: "ABX Tokens Unlocked",
        description: `Successfully unlocked ABX tokens from lock #${tokenId}`,
        hash: transactionHash,
        action: "unlock"
      }
    }, `lock-unlock-${transactionHash}`, 8e3);
    await refetchUserLocks();
    setTimeout(() => {
      setFlowState({ step: "idle" });
    }, 3e3);
  }, [transactionHash, refetchUserLocks]);
  useEffect(() => {
    if (isConfirming && flowState.step === "confirming") {
      setFlowState((current) => ({
        ...current,
        transactionHash
      }));
    } else if (isSuccess && flowState.step === "confirming" && flowState.tokenId) {
      handleSuccess(flowState.tokenId);
    } else if (writeError && flowState.step === "confirming") {
      const errorMessage = writeError.message;
      const isUserRejection = errorMessage.toLowerCase().includes("user rejected") || errorMessage.toLowerCase().includes("user denied") || errorMessage.toLowerCase().includes("rejected by user");
      if (isUserRejection) {
        setFlowState({ step: "idle" });
        popupRegistry.addPopup({
          type: PopupType.LockError,
          content: {
            type: "error",
            title: "Transaction Cancelled",
            description: "Unlock transaction was cancelled by user",
            action: "withdraw"
          }
        }, `lock-unlock-cancelled-${Date.now()}`, 5e3);
      } else {
        setFlowState({
          step: "error",
          error: errorMessage,
          tokenId: flowState.tokenId
        });
        popupRegistry.addPopup({
          type: PopupType.LockError,
          content: {
            type: "error",
            title: "Unlock Failed",
            description: `Failed to unlock ABX tokens: ${errorMessage}`,
            action: "withdraw"
          }
        }, `lock-unlock-error-${Date.now()}`, 1e4);
      }
    }
  }, [isConfirming, isSuccess, writeError, transactionHash, flowState, handleSuccess]);
  return {
    // Flow state  
    flowState,
    // Actions
    executeUnlock,
    // Loading states
    isProcessing: isWritePending || isConfirming,
    // Account
    isConnected: !!account
  };
}
