"use strict";
import { useCallback, useMemo } from "react";
import { useChainId, useReadContracts } from "wagmi";
import { getContractAbi, getContractAddress } from "uniswap/src/constants/contracts";
export function useManagedDeposits(locks = []) {
  const chainId = useChainId();
  const votingEscrowAddress = getContractAddress(chainId, "VotingEscrow");
  const votingEscrowAbi = getContractAbi(chainId, "VotingEscrow");
  const locksKey = useMemo(() => locks.map((lock) => lock.id).join(","), [locks]);
  const idToManagedContracts = useMemo(() => {
    if (!locks.length || !votingEscrowAddress || !votingEscrowAbi) {
      return [];
    }
    const prepared = [];
    locks.forEach((lock) => {
      try {
        prepared.push({
          address: votingEscrowAddress,
          abi: votingEscrowAbi,
          functionName: "idToManaged",
          args: [BigInt(lock.id)]
        });
      } catch (error) {
        console.warn("useManagedDeposits: failed to parse lock id", lock.id, error);
      }
    });
    return prepared;
  }, [locksKey, locks.length, votingEscrowAddress, votingEscrowAbi]);
  const {
    data: depositData,
    isLoading: depositLoading,
    refetch: refetchDeposits
  } = useReadContracts({
    contracts: idToManagedContracts,
    query: {
      enabled: idToManagedContracts.length > 0,
      staleTime: 3e4,
      refetchInterval: 6e4,
      refetchOnWindowFocus: false,
      refetchOnMount: false
    }
  });
  const { depositEntries, depositedPairs } = useMemo(() => {
    const entries = [];
    const pairs = [];
    if (!locks.length || !depositData) {
      locks.forEach((lock) => {
        entries.push([
          lock.id,
          {
            managedTokenId: null,
            isDeposited: false,
            managedAmount: null
          }
        ]);
      });
      return { depositEntries: entries, depositedPairs: pairs };
    }
    locks.forEach((lock, index) => {
      const result = depositData[index]?.result;
      const hasManaged = !!result && result !== 0n;
      const managedTokenId = hasManaged ? result.toString() : null;
      entries.push([
        lock.id,
        {
          managedTokenId,
          isDeposited: hasManaged,
          managedAmount: null
        }
      ]);
      if (hasManaged && managedTokenId) {
        try {
          const lockIdBigInt = BigInt(lock.id);
          pairs.push({
            lockId: lock.id,
            managedTokenId,
            lockIdBigInt,
            managedTokenIdBigInt: result
          });
        } catch (error) {
          console.warn("useManagedDeposits: failed to parse ids for weight query", lock.id, managedTokenId, error);
        }
      }
    });
    return { depositEntries: entries, depositedPairs: pairs };
  }, [locksKey, locks, depositData]);
  const weightContracts = useMemo(() => {
    if (!depositedPairs.length || !votingEscrowAddress || !votingEscrowAbi) {
      return [];
    }
    return depositedPairs.map((entry) => ({
      address: votingEscrowAddress,
      abi: votingEscrowAbi,
      functionName: "weights",
      args: [entry.lockIdBigInt, entry.managedTokenIdBigInt]
    }));
  }, [depositedPairs, votingEscrowAddress, votingEscrowAbi]);
  const {
    data: weightData,
    isLoading: weightsLoading,
    refetch: refetchWeights
  } = useReadContracts({
    contracts: weightContracts,
    query: {
      enabled: weightContracts.length > 0,
      staleTime: 3e4,
      refetchInterval: 6e4,
      refetchOnWindowFocus: false,
      refetchOnMount: false
    }
  });
  const weightMap = useMemo(() => {
    const map = /* @__PURE__ */ new Map();
    if (!weightData || !depositedPairs.length) {
      return map;
    }
    depositedPairs.forEach((entry, index) => {
      const weight = weightData[index]?.result;
      if (typeof weight === "bigint") {
        map.set(entry.lockId, weight.toString());
      }
    });
    return map;
  }, [depositedPairs, weightData]);
  const depositMap = useMemo(() => {
    const map = /* @__PURE__ */ new Map();
    depositEntries.forEach(([lockId, info]) => {
      const managedAmount = weightMap.get(lockId) ?? null;
      map.set(lockId, {
        ...info,
        managedAmount
      });
    });
    return map;
  }, [depositEntries, weightMap]);
  const combinedLoading = depositLoading || weightContracts.length > 0 && weightsLoading;
  const refetchAll = useCallback(() => {
    const promises = [];
    promises.push(refetchDeposits());
    if (weightContracts.length > 0) {
      promises.push(refetchWeights());
    }
    return Promise.all(promises).catch((error) => {
      console.error("useManagedDeposits: failed to refetch deposits", error);
    });
  }, [refetchDeposits, refetchWeights, weightContracts.length]);
  return {
    depositMap,
    isLoading: combinedLoading,
    refetch: refetchAll
  };
}
export function useLockDepositStatus(lock) {
  const lockArray = useMemo(() => lock ? [lock] : [], [lock]);
  const { depositMap, isLoading, refetch } = useManagedDeposits(lockArray);
  const info = lock ? depositMap.get(lock.id) : void 0;
  const isDeposited = Boolean(info?.isDeposited && info.managedTokenId);
  const managedTokenId = info?.managedTokenId ?? null;
  const managedAmount = info?.managedAmount ?? null;
  return {
    isDeposited,
    managedTokenId,
    managedAmount,
    info,
    isLoading,
    refetch
  };
}
export function useRelayStatuses(relayIds = []) {
  const chainId = useChainId();
  const votingEscrowAddress = getContractAddress(chainId, "VotingEscrow");
  const votingEscrowAbi = getContractAbi(chainId, "VotingEscrow");
  const relayIdsKey = useMemo(() => relayIds.join(","), [relayIds]);
  const contracts = useMemo(() => {
    if (!relayIds.length || !votingEscrowAddress || !votingEscrowAbi) {
      return [];
    }
    return relayIds.map((relayId) => ({
      address: votingEscrowAddress,
      abi: votingEscrowAbi,
      functionName: "deactivated",
      args: [BigInt(relayId)]
    }));
  }, [relayIdsKey, relayIds.length, votingEscrowAddress, votingEscrowAbi]);
  const { data, isLoading, refetch } = useReadContracts({
    contracts,
    query: {
      enabled: contracts.length > 0,
      staleTime: 3e4,
      refetchInterval: 6e4,
      refetchOnWindowFocus: false,
      refetchOnMount: false
    }
  });
  const statusMap = useMemo(() => {
    const map = /* @__PURE__ */ new Map();
    if (!relayIds.length || !data) {
      relayIds.forEach((relayId) => {
        map.set(relayId, { isActive: true });
      });
      return map;
    }
    relayIds.forEach((relayId, index) => {
      const isDeactivated = Boolean(data[index]?.result);
      map.set(relayId, { isActive: !isDeactivated });
    });
    return map;
  }, [relayIdsKey, relayIds, data]);
  return {
    statusMap,
    isLoading,
    refetch
  };
}
