"use strict";
import { useMemo } from "react";
import { useReadContracts, useChainId } from "wagmi";
import { getContractAddress, getContractAbi } from "uniswap/src/constants/contracts";
const EPOCH_DURATION = 604800;
const POKE_THRESHOLD = 0.01;
export function usePokeStatus(locks) {
  const chainId = useChainId();
  const voterAddress = getContractAddress(chainId, "Voter");
  const voterAbi = getContractAbi(chainId, "Voter");
  const locksKey = useMemo(() => locks.map((l) => l.id).join(","), [locks]);
  const currentEpochStart = useMemo(() => {
    const now = Math.floor(Date.now() / 1e3);
    return BigInt(Math.floor(now / EPOCH_DURATION) * EPOCH_DURATION);
  }, []);
  const contracts = useMemo(() => {
    return locks.flatMap((lock) => [
      {
        address: voterAddress,
        abi: voterAbi,
        functionName: "usedWeights",
        args: [BigInt(lock.id)]
      },
      {
        address: voterAddress,
        abi: voterAbi,
        functionName: "lastVoted",
        args: [BigInt(lock.id)]
      }
    ]);
  }, [locksKey, voterAddress, voterAbi]);
  const { data, isLoading, refetch } = useReadContracts({
    contracts,
    query: {
      enabled: locks.length > 0 && !!voterAddress && !!voterAbi,
      staleTime: 3e4,
      // 30 seconds
      refetchInterval: 6e4,
      // 1 minute
      refetchOnWindowFocus: false,
      refetchOnMount: false
    }
  });
  const pokeStatusMap = useMemo(() => {
    const statusMap = /* @__PURE__ */ new Map();
    if (!data || isLoading) {
      return statusMap;
    }
    locks.forEach((lock, index) => {
      const baseIndex = index * 2;
      const usedWeightResult = data[baseIndex]?.result;
      const lastVotedResult = data[baseIndex + 1]?.result;
      const usedWeight = usedWeightResult ?? 0n;
      const lastVoted = lastVotedResult ?? 0n;
      const currentBalance = BigInt(lock.votingPower);
      const hasVotedThisEpoch = lastVoted >= currentEpochStart;
      let percentDifference = 0;
      if (usedWeight > 0n) {
        const diff = currentBalance - usedWeight;
        percentDifference = Number(diff * 10000n / usedWeight) / 100;
      }
      const needsPoke = hasVotedThisEpoch && currentBalance > usedWeight && percentDifference > POKE_THRESHOLD * 100;
      statusMap.set(lock.id, {
        lockId: lock.id,
        needsPoke,
        currentBalance,
        usedWeight,
        lastVoted,
        percentDifference
      });
    });
    return statusMap;
  }, [data, isLoading, locks, locksKey, currentEpochStart]);
  const locksNeedingPoke = useMemo(() => {
    const lockIds = /* @__PURE__ */ new Set();
    pokeStatusMap.forEach((status, lockId) => {
      if (status.needsPoke) {
        lockIds.add(lockId);
      }
    });
    return lockIds;
  }, [pokeStatusMap]);
  return useMemo(
    () => ({
      pokeStatusMap,
      locksNeedingPoke,
      isLoading,
      needsPoke: (lockId) => locksNeedingPoke.has(lockId),
      getPokeStatus: (lockId) => pokeStatusMap.get(lockId),
      refetch
    }),
    [pokeStatusMap, locksNeedingPoke, isLoading, refetch]
  );
}
